226			),
227	
228			createTool(
229				"set_learner_goal",
230				"Capture what the learner wants to ACCOMPLISH (a task or project) and build a long-horizon, multi-step curriculum that scaffolds toward it. The goal is persisted and its progress is tracked across sessions. Design the `steps` yourself as an ordered path (concept → practice → project → reflection); if you omit steps, a scaffold is generated from the anchor topic. Use update_goal_step to advance it later.",
231				{
232					title: { type: "string", description: "The goal/task the learner wants to accomplish (e.g. 'Build a personal-finance tracker app')" },
233					description: { type: "string", description: "What success looks like / scope of the goal" },
234					motivation: { type: "string", description: "Why the learner wants this — used to keep them oriented" },
235					target_date: { type: "string", description: "Optional target date or timeframe (free text)" },
236					topic: { type: "string", description: "Anchor topic used to auto-scaffold steps when `steps` is omitted" },
237					steps: {
238						type: "array",
239						description: "Ordered curriculum steps building toward the goal",
240						items: {
241							type: "object",
242							properties: {
243								title: { type: "string", description: "Step title" },
244								description: { type: "string", description: "What the learner does in this step" },
245								kind: { type: "string", description: "One of: concept, practice, project, milestone, reflection" },
246								topic: { type: "string", description: "Topic this step centers on (enables plan/quiz tooling)" },
247								success_criteria: { type: "array", items: { type: "string" }, description: "How the learner knows this step is done" },
248							},
249						},
250					},
251				},
252				async (params) => {
253					const title = String(params.title ?? "").trim();
254					if (!title) return "Error: a goal title is required.";
255	
256					const rawSteps = Array.isArray(params.steps) ? params.steps : [];
257					const steps: GoalStepInput[] = rawSteps
258						.filter((s): s is Record<string, unknown> => !!s && typeof s === "object")
259						.map((s) => ({
260							title: String(s.title ?? ""),
261							description: s.description ? String(s.description) : undefined,
262							kind: s.kind ? (String(s.kind) as GoalStepInput["kind"]) : undefined,
263							topic: s.topic ? String(s.topic) : undefined,
264							successCriteria: Array.isArray(s.success_criteria)
265								? (s.success_criteria as unknown[]).filter((c): c is string => typeof c === "string")
266								: undefined,
267						}));
268	
269					const goal = buildGoal({
270						title,
271						description: params.description ? String(params.description) : undefined,
272						motivation: params.motivation ? String(params.motivation) : undefined,
273						targetDate: params.target_date ? String(params.target_date) : undefined,
274						topic: params.topic ? String(params.topic) : undefined,
275						steps: steps.length > 0 ? steps : undefined,
276					});
277	
278					const saved = await storage.saveGoal(goal);
279					const progress = computeGoalProgress(saved);
280					const summary = [
281						`Created goal **${saved.title}** with ${saved.steps.length} steps.`,
282						progress.nextStep ? `First up: ${progress.nextStep.title}.` : "",
283						"The learner can tap steps in the card below to track progress.",
284					]
285						.filter(Boolean)
286						.join(" ");
287					return `${summary}\n\n<keating-goal json=${JSON.stringify(JSON.stringify(saved))} />`;
288				}
289			),
290	
291			// list_learner_goals - Show the learner's goals and progress
292			createTool(
293				"list_learner_goals",
294				"Legacy on-demand goal listing. Active goals and next steps are loaded automatically before the first model turn; prefer inspect_learning_context when full goal details are needed.",
295				{
296					status: { type: "string", description: "Optional filter: active, completed, or paused" },
297				},
298				async (params) => {
299					const filter = params.status ? String(params.status) : undefined;
300					let goals = await storage.getGoals();
301					if (filter) goals = goals.filter((g) => g.status === filter);
302					if (goals.length === 0) return "No saved goals yet. Use set_learner_goal to create one.";
303					const lines = goals.map((g) => {
304						const p = computeGoalProgress(g);
305						const next = p.nextStep ? ` — next: ${p.nextStep.title}` : "";
306						return `- **${g.title}** (${g.status}) — ${p.done}/${p.total} steps, ${p.percent}%${next}  \`${g.id}\``;
307					});
308					return `## Learner goals\n\n${lines.join("\n")}`;
309				}
310			),
311	
312			// update_goal_step - Advance a step in a goal's curriculum
313			createTool(
314				"update_goal_step",
315				"Mark a curriculum step's status to track progress toward a goal. Persists across sessions and recomputes overall goal completion.",
316				{
317					goal_id: { type: "string", description: "The goal id (from set_learner_goal or list_learner_goals)" },
318					step_id: { type: "string", description: "The step id to update" },
319					status: { type: "string", description: "New status: not_started, in_progress, or done" },
320				},
321				async (params) => {
322					const goalId = String(params.goal_id ?? "");
323					const stepId = String(params.step_id ?? "");
324					const status = String(params.status ?? "") as GoalStepStatus;
325					if (!goalId || !stepId) return "Error: goal_id and step_id are required.";
326					if (!["not_started", "in_progress", "done"].includes(status)) {
327						return "Error: status must be not_started, in_progress, or done.";
328					}
329					const goal = await storage.getGoal(goalId);
330					if (!goal) return `Error: no goal found with id ${goalId}.`;
331					if (!goal.steps.some((s) => s.id === stepId)) {
332						return `Error: goal ${goalId} has no step ${stepId}.`;
333					}
334					const updated = advanceGoalStep(goal, stepId, status);
335					const saved = await storage.saveGoal(updated);
336					const progress = computeGoalProgress(saved);
337					const next = progress.nextStep ? `Next: ${progress.nextStep.title}` : "All steps complete! 🎉";
338					return `Updated "${saved.title}" → ${progress.done}/${progress.total} steps (${progress.percent}%). ${next}\n\n<keating-goal json=${JSON.stringify(JSON.stringify(saved))} />`;
339				}
340			),
341	
342			// source_edit - Apply a search/replace edit inside the NodePod VFS
343		];
344	}
345	
346	/**
347	 * Optional, consolidated access to learner history that is intentionally kept
348	 * out of the baseline schema set. Session hooks already provide the compact
349	 * context needed for ordinary teaching.
350	 */
351	export function createLearnerContextCapabilityTools(registry: ToolRegistry): AgentTool[] {
352		return [
353			createTool(
354				"inspect_learning_context",
355				"Inspect selected parts of the learner's durable context when the automatically loaded session summary is not enough. Request all related sections in one call. Do not call this merely to bootstrap a conversation.",
356				{
357					sections: {
358						type: "array",
359						minItems: 1,
360						uniqueItems: true,
361						items: { type: "string", enum: ["profile", "timeline", "due_reviews", "goals"] },
362						description: "The deeper learner-context sections needed for the current teaching decision.",
363					},
364					goal_status: {
365						type: "string",
366						enum: ["active", "completed", "paused"],
367						description: "Optional status filter, used only when goals is requested.",
368					},
369				},
370				async (params) => {
371					const requested = Array.isArray(params.sections)
372						? [...new Set(params.sections.filter((section): section is string => typeof section === "string"))]
373						: [];
374					const toolBySection: Record<string, string> = {
375						profile: "learner_state",
376						timeline: "timeline",
377						due_reviews: "due",
378						goals: "list_learner_goals",
379					};
380					const sections: string[] = [];
381					for (const section of requested) {
382						const toolName = toolBySection[section];
383						if (!toolName) continue;
384						const output = await registry.invoke(toolName, section === "goals" && params.goal_status
385							? { status: params.goal_status }
386							: {});
387						sections.push(`## ${section.replaceAll("_", " ")}\n\n${output}`);
388					}
389					return sections.join("\n\n---\n\n") || "No valid learner-context sections were requested.";
390				},
391				["sections"],
392			),
393		];
394	}
395	
396	function slugifyDeckTitle(value: string): string {
397		return value
398			.toLowerCase()
399			.trim()
400			.replace(/[^a-z0-9]+/g, "-")
401			.replace(/^-+|-+$/g, "")
402			.slice(0, 80);
403	}
404	
405	function draftDeckCardId(deckSlug: string, index: number): string {
406		if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
407			return `${deckSlug}-${crypto.randomUUID()}`;
408		}
409		return `${deckSlug}-${Date.now()}-${index + 1}`;
410	}
411	// Internal-only exports so unit tests can drive the helpers without needing
412	// to instantiate the full agent tool set.
413

