import { relative } from "node:path";
import {
  animateTopicArtifact,
  mapTopicArtifact,
  planTopicArtifact,
  verifyTopicArtifact
} from "../../../core/project.js";
import { generateQuiz, quizToMarkdown, quizAnswerKeyToMarkdown, type Quiz } from "../../../core/quiz.js";
import { learnerStatePath } from "../../../core/paths.js";
